class Clock{
	int h,m,s;
	void doit(int t){
		int tmp = t;
		s = tmp % 60;
		tmp /= 60;
		m = tmp % 60;
		tmp /= 60;
		h = tmp;
		System.out.println(h + ":" + m + ":" + s);
	}
}

