	private void calc(){
		Scanner scanner = new Scanner(System.in);
		int time =scanner.nextInt();

			int hour=time/3600;
			int min =(time-(3600*hour))/60;
			int sec =time-(3600*hour+60*min);
			System.out.print(hour +":"+ min + ":"+sec);
			System.out.println("");

	}

	public static void main(String[] args) {
		Main cubic =new Main();
		cubic.calc();

	}
}

