	public static void outSumOfNumbers(String numStr) {
		byte[] sbyte = new byte[numStr.length()];
		int sum = 0;

		for (int i = 0; i < numStr.length(); i++) {
			sbyte[i] = (byte) numStr.charAt(i);
			sbyte[i] -= 48;
			sum += sbyte[i];
		}

		System.out.println(sum);
	}

