    }

    private static String problem161a(int x, int y, int z) {
        int[] array = {x, y, z};
        swap(array, 0, 1);
        swap(array, 0, 2);
        return array[0] + " " + array[1] + " " + array[2];
    }

    private static void swap(int[] array, int idx1, int idx2) {
        int tmp = array[idx1];
        array[idx1] = array[idx2];
        array[idx2] = tmp;
    }
}

