            } else if (k == 1) {
                out.println(0);
                return;
            } else if (n < k) {
                x = Math.abs(n - k);
                if (x < n) {
                    out.println(x);
                } else {
                    out.println(n);
                }
                return;
            } else if (n > k) {
                if (n % k == 0) {
                    out.println(0);
                    return;

                } else if (n % k == 1) {
                    out.println(1);
                    return;

                } else {
                    x = Math.abs(n % k - k);
                    if (n % k > x) {
                        out.println(x);
                        return;

                    } else {
                        out.println(n % k);
                        return;

                    }

                }
            } else {
                out.println(0);
                return;
            }

        }

    }
}

