            System.out.println(Math.min(N,Math.abs(N-K)));
        }
        else if(N>K){
            long q = N/K -1;
            N = N - q*K;
            N = Math.abs(N-K);
            System.out.println(Math.min(N,Math.abs(N-K)));
        }
        else System.out.println(0);
    }
}

