    }

    void solve(PrintWriter out) {
        List<String> days = new ArrayList<>();

        String[] s = { "SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT" };

        for (int i = s.length - 1; i >= 0; i--) {
            days.add(s[i]);
        }

        //out.println(days);
        out.println(days.indexOf(day) + 1);

    }
}

