        String s = arr02[0];

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int x = (int) c;

            if (x + n <= 65 + 25) {

                sb.append(String.valueOf((char) (x + n)));
            } else {
                sb.append(String.valueOf((char) (x + n - 26)));
            }
        }

        System.out.println(sb);
    }

