class Solver {
    public void solve(long N, String S) {
        for (int i = 0; i < S.length(); i++) {
            int up = (int) ((S.charAt(i) - 'A' + N) / 26);
            char alpha = (char) (S.charAt(i) + N - up * 26);

            System.out.print(alpha);
        }
        System.out.println();
    }
}

