		for (int i=1; i<=q; i++){
			int ai = sc.nextInt();
			a [ai]++;
		}
		//out.println(a[4]);

		for (int i=1; i<=n; i++){
			if (k-(q-a[i])>0)
				out.println("Yes");
			else
