    }

    public static void solve(int n, int q, long k, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < q; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (q - k >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

