			c[i] = in.nextInt();
		System.out.println(solve(n, a, b, c));
		in.close();
	}

	private static int solve(int n, int[] a, int[] b, int[] c) {
		int r = 0;
		for (int i = 0; i < n; i++) {
			r += b[a[i]];
			if (i < n - 1)
				if (a[i] + 1 == a[i + 1])
					r += c[a[i]];
		}
		return r;
	}
}

