        for (int i = 0; i < elements-1; i++) {
            bonus[i] = sc.nextInt();
        }

        solve(order,point,bonus);
    }

    public static void solve(int[] order,int[] point,int[] bonus){
        int result = 0;
        int prev = order.length;
        for(int now:order){
            result += point[now];
            if(now-prev==1){
                result += bonus[prev];
            }
            prev = now;
        }
        System.out.println(result);
    }
}

