        System.out.println(ans);
    }
    public static int WeatherMatch(String S, String T) {
        if (S.length() == 0) {
            return 0;
        }
        if (S.charAt(0) == T.charAt(0)) {
            return 1 + WeatherMatch(S.substring(1), T.substring(1));
        }
        return WeatherMatch(S.substring(1), T.substring(1));
    }
}

