		char s[] = getString().toCharArray();
		char t[] = getString().toCharArray();
		int ans = ( s[0]==t[0] ? 1 : 0 ) + ( s[1]==t[1] ? 1 : 0 ) + ( s[2]==t[2] ? 1 : 0 ) ;
		System.out.println(ans);
	}
}

