                if (y <= threshold) {
                    if (foo == -1 || foo > x) {
                        foo = x;
                    }
                }
            }
            if (foo >= 0) {
                stdout.printf("%d\n", foo);
            } else {
                stdout.printf("TLE\n");
            }
        }

        this.stdin.close();
        this.stdout.close();
    }

    public static void main(String[] args) throws Exception {
        Main instance = new Main();
        instance.execute();
    }

}

