	//static final int INF = 1000000007;

	//static long[] factorial;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int N = sc.ni();
		int Y = sc.ni();
		for (int i = 0; i <= N; i++) {
			for (int j = 0; j <= N-i; j++) {
				int k = N-i-j;
				if (10000*i+5000*j+1000*k == Y) {
					pw.println(i + " " + j + " " + k);
					pw.close();
					return;
				}
			}
		}
		pw.println("-1 -1 -1");
		pw.close();
