	public static void solve(FastScanner sc, PrintWriter out) {
		int n = sc.nextInt();
		int y = sc.nextInt();

		for(int i = 0; i <= n; i++) {
			for(int j = 0; j <= n-i; j++) {
				int k = n-i-j;

				if(i*10000+j*5000+k*1000 == y) {
