class AtCoder {

    final int N, Y;
    int x, y, z;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        Y = sc.nextInt();
        x = -1;
        y = -1;
        z = -1;
    }

    void solve(PrintWriter out) {
        outer:
        for (int i = N; i >= 0; i--) {
            for (int j = N - i; j >= 0; j--) {
                int k = Math.max(0, N - i - j);
                if (i * 10000 + j * 5000 + k * 1000 == Y) {
                    x = i;
                    y = j;
                    z = k;
                    break outer;
                }
            }
        }
        out.println(x + " " + y + " " + z);
    }
}
