            for (int j = 0; j <= N - i; j++) {
                if (remain1 < j * 5000) {
                    continue;
                }
                int remain2 = remain1 - j * 5000;
                if (N - i - j == remain2 / 1000) {
                    a[0] = i;
                    a[1] = j;
                    a[2] = N - i - j;
                    break;
                }
            }
            if (found) {
                break;
            }
        }
        System.out.printf("%d %d %d\n",a[0],a[1],a[2]);

    }
}

