class Solver {
    public void solve(String a, String b, String c) {
        String ans = "";
        char turn = 'a';
        int an = a.length();
        int bn = b.length();
        int cn = c.length();
        while (true) {
            if (turn == 'a') {
                if (an == 0) {
                    ans = "A";
                    break;
                }
                turn = a.charAt(a.length() - an);
                an--;
            }

            if (turn == 'b') {
                if (bn == 0) {
                    ans = "B";
                    break;
                }
                turn = b.charAt(b.length() - bn);
                bn--;
            }

            if (turn == 'c') {
                if (cn == 0) {
                    ans = "C";
                    break;
                }

                turn = c.charAt(c.length() - cn);
                cn--;
            }
        }
        Main.output.append(ans);
    }
