        char player = 'a';
        while(true){
            if(player=='a'){
                if(!a.isEmpty()){
                    player = a.pollFirst();
                }else break;
            }else if(player=='b'){
                if(!b.isEmpty()){
                    player = b.pollFirst();
                }else break;
            }else{
                if(!c.isEmpty()){
                    player = c.pollFirst();
                }else break;
            }
        }
        out.println((char)(player+'A'-'a'));
    }

