		Stack<Character> stack = new Stack<>();
		for (int i = 0; i < s.length(); ++i) {
			char ch = s.charAt(i);
			if (ch == 'B') {
				if (!stack.isEmpty()) stack.pop();
			} else {
				stack.push(ch);
